    private void btnIngresarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnIngresarActionPerformed
        String nombreUsuario = txtUsuario.getText().trim();
        String contrasena = new String(txtContrasena.getPassword());

        //validación de campos vacíos
        if (nombreUsuario.isEmpty() || contrasena.isEmpty()) {
            javax.swing.JOptionPane.showMessageDialog(this,
                "Ingrese usuario y contraseña.", "Campos incompletos",
                javax.swing.JOptionPane.WARNING_MESSAGE);
            return;
        }

        //FALTA validación de usuario y contraseña
        String usuario = txtUsuario.getText().trim();
        VentanaPrincipal principal = new VentanaPrincipal(usuario);
        principal.setVisible(true);
        principal.setLocationRelativeTo(null);
        principal.setTitle("Sistema de matrículas - VallejoMatricula");
        dispose();
    }//GEN-LAST:event_btnIngresarActionPerformed

    private void btnVerContrasenaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnVerContrasenaActionPerformed
        //all darle click al boton, el usuario podrá ver la contraseña ingresada
        if (!visible) {
            txtContrasena.setEchoChar((char) 0);
            btnVerContrasena.setText("Ocultar");
            visible = true;
        } else {
            txtContrasena.setEchoChar('*');
            btnVerContrasena.setText("Ver");
            visible = false;
        }
    }//GEN-LAST:event_btnVerContrasenaActionPerformed

